function compileInputSchema(ajv: Ajv.Ajv, name: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${name}"`, {cause: error});
  }
}

function describeValidationError(error: ErrorObject): string {
  const path = error.dataPath.slice(1);
  if ('missingProperty' in error.params) {
    return `${error.params.missingProperty} is required`;
  }
  return `${path} ${error.message}`;
}

