function describeValidationError(error: ErrorObject): string {
  const path = error.dataPath.startsWith('.') ? error.dataPath.slice(1) : error.dataPath;
  if (error.keyword === 'required' && 'missingProperty' in error.params) {
    const field = path ? `${path}.${error.params.missingProperty}` : error.params.missingProperty;
    return `${field} is required`;
  }
  const target = path || 'input';
  if (error.keyword === 'type' && 'type' in error.params) {
    return `${target} must be ${error.params.type}`;
  }
  return `${target} ${error.message ?? `failed ${error.keyword}`}`;
}

